import React, { useState } from 'react';
import { Box, Paper, Tabs, Tab, Typography, Avatar } from '@mui/material';
import AddCircleIcon from '@mui/icons-material/AddCircle';
import ListAltIcon from '@mui/icons-material/ListAlt';
import SalaryForm from './SalaryForm';
import SalaryList from './SalaryList';

/**
 * Salary sub-tab container with two views:
 *  0 - ثبت فیش حقوق جدید
 *  1 - لیست حقوق
 */
const SalaryTab = ({ onSuccess }) => {
  const [subTab, setSubTab] = useState(0);

  return (
    <Box>
      <Paper sx={{ mb: 2, overflow: 'hidden' }}>
        <Tabs
          value={subTab}
          onChange={(e, v) => setSubTab(v)}
          variant="fullWidth"
          sx={{
            borderBottom: 1,
            borderColor: 'divider',
            bgcolor: 'rgba(245,158,11,0.04)',
          }}
        >
          <Tab
            icon={<AddCircleIcon />}
            iconPosition="start"
            label="ثبت فیش حقوق جدید"
            sx={{ color: subTab === 0 ? '#f59e0b' : undefined, fontWeight: 600 }}
          />
          <Tab
            icon={<ListAltIcon />}
            iconPosition="start"
            label="لیست حقوق"
            sx={{ color: subTab === 1 ? '#f59e0b' : undefined, fontWeight: 600 }}
          />
        </Tabs>
      </Paper>

      <Box>
        {subTab === 0 && <SalaryForm onSuccess={onSuccess} />}
        {subTab === 1 && <SalaryList />}
      </Box>
    </Box>
  );
};

export default SalaryTab;
